CREATE OR REPLACE SECURE VIEW DP_GENERATION.OUT_REC_CERTIFICATE
  WITH TAG (GOV.DATA_CLASSIFICATION = 'Internal - Restricted', GOV.DATA_OWNER = 'Energy Data Engineering Team', GOV.DOMAIN = 'Energy_Generation_Package')
  COMMENT = 'Atomic contracted output for RECCertificate'
AS
SELECT f.REC_ID, f.DATE_KEY, f.SOURCE_ID, f.POWER_PLANT_ID, f.EXPIRY_DATE, f.STATUS, f.MWH, d1.FISCAL_YEAR, d1.FULL_DATE, d1.IS_HOLIDAY, d1.IS_WEEKEND, d1.MONTH_NAME, d1.MONTH_NUMBER, d1.QUARTER, d2.IS_REC_ELIGIBLE, d2.SOURCE_CATEGORY, d2.SOURCE_NAME, d3.PLANT_NAME, d3.PLANT_TYPE, d3.REGION
FROM CORE.FCT_REC_CERTIFICATE f
LEFT JOIN CORE.DIM_DATE d1 ON f.DATE_KEY = d1.DATE_KEY
LEFT JOIN CORE.DIM_ENERGY_SOURCE d2 ON f.SOURCE_ID = d2.SOURCE_ID
LEFT JOIN CORE.DIM_POWER_PLANT d3 ON f.POWER_PLANT_ID = d3.POWER_PLANT_ID;
